    const w = (r, d) => { if (!r || d > 14 || !r.querySelectorAll) return; r.querySelectorAll('bubble-card').forEach((b) => bcs.push(b)); r.querySelectorAll('*').forEach((e) => { if (e.shadowRoot) w(e.shadowRoot, d + 1); }); };
    w(document, 0);
