          M.profileSet(HPROF, { people_order: list.map((r) => r && r.person).filter(Boolean), people_hidden: list.filter((r) => r && r.hidden && r.person).map((r) => r.person) }, this._pkey(), { commit: commit !== false });
          this._noProf = true;
