        const si = pend.sleep ? pend.sleep.i : p.sleep ? 1 : 0;
        const place = pend.zone ? (zi === 0 ? 'Hjemme' : 'Borte') : p.place;
        const slp = pend.sleep ? si === 1 : p.sleep;
