    price: (h) => (M.powerPrice ? M.powerPrice(h).entity : null),
    watt: (h) => M.kiRomId(h, null, 'effekt') || null,
    lights: (h) => M.kiRomId(h, null, 'lys') || null,
    lock: (h) => M.all(h, 'lock')[0] || null,
