    if (ts && M.isNum(ts.state)) S.temp = [deg(ts.state), Number(ts.state), null, E.temp];
    else if (w && M.isNum(w.attributes.temperature)) S.temp = [deg(w.attributes.temperature), Number(w.attributes.temperature), null, E.weather];
