      if (!tv) t('Fant ingen TV'); else M.call(h, 'media_player', 'toggle', { entity_id: tv }).then(() => t(M.isOn(h.states[tv]) || h.states[tv].state === 'on' ? 'TV slått av' : 'TV slått på')).catch(() => {});
