      const w = c.tab_width || 'std';
      const tw = w === 'custom' ? `width:${Number(c.tab_width_px) || 88}px;` : '';
      const pad = w === 'custom' ? '0 6px' : w === 'kompakt' ? '0 12px' : '0 18px';
      const P = (this._tabPos || {})[(TV[idx] || {}).id];
