      let a = cfg[TAP_KEYS[w]];
      if (a == null || a === '') a = w === 'hold_ic' ? cfg.icon_hold_action : w === 'hold_card' ? cfg.hold_action : cfg.tap_action;
      a = M.tap ? M.tap.norm(a) : null;
