      if (w === 'ic') return t && t.ic ? { action: 'toggle' } : this._tapFor(id, 'card', t);
      if (w === 'card') { const h = tp.card_hash || (t && t.cardHash); return h ? NAV(h) : { action: 'more-info' }; }
