      A.popups.forEach((p, i) => { const bad = !!p.err || !HASH_RX.test(normH(p.cfg && p.cfg.hash)); list += chk(i, !bad && sel[i] !== false, bad, (p.cfg && p.cfg.icon) || 'mdi:card-outline', (p.cfg && (p.cfg.name || p.cfg.hash)) || 'Popup ' + (i + 1), st(p)); });
