    const out = [{ type: 'boolean', name: ownPath, label: 'Egne varsel-vilkår', help: own ? 'Første vilkår som slår til vises som «!» på rommet. Ingen vilkår = aldri varsel.' : `Standard: ${defs.join(' · ') || 'ingen'}` }];
