  M.parseNum = M.parseNum || ((v, d) => { const n = parseFloat(String(v == null ? '' : v).replace(',', '.')); return isNaN(n) ? d : n; });
  M.parseHM = M.parseHM || ((v, d) => { const m = /(\d{1,2})[:.](\d{2})/.exec(String(v || '')); return m ? Number(m[1]) + Number(m[2]) / 60 : d; });
