          if (m.e.os_controller && m.all.some((z) => z.os)) await M.call(h, 'opensprinkler', 'stop', { entity_id: m.e.os_controller });
          await Promise.all(m.all.filter((z) => z.running && !z.os).map((z) => M.vanStop(h, z)));
